// Green 5 s, yellow 2 s, red 5 s, forever.
const int RED = 10, YELLOW = 9, GREEN = 8;

void light(int pin, unsigned long ms) {
  digitalWrite(pin, HIGH);
  delay(ms);
  digitalWrite(pin, LOW);
}

void setup() {
  pinMode(RED, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(GREEN, OUTPUT);
}

void loop() {
  light(GREEN, 5000);
  light(YELLOW, 2000);
  light(RED, 5000);
}
